import { stat } from 'node:fs/promises';
import type { ResolvedTarget } from '../../targets/targets.js';

/**
 * The overlay layered on top of Signals-DPG/local-setup/docker-compose.yml.
 *
 * That file is the authoritative local stack and already carries postgres,
 * redis, stock Keycloak with its mounts, the user-profile fixup, mailpit, the
 * bootstrap tools one-shot, signals-api, TEI and signals-search api+worker.
 * The harness changes only what a verification run needs and inherits
 * everything else, including the reasoning in its comments.
 */
export function renderOverlay(opts: {
  target: ResolvedTarget;
  digests: Record<string, string>;
  timing: Record<string, string>;
  /** Absolute path to the aggregator-dpg checkout (render script + themes). */
  aggregatorRoot?: string;
  /** Directory holding the prepared realm export (see prepareRealm). */
  realmDir?: string;
}): string {
  const { target, digests, timing, aggregatorRoot, realmDir } = opts;
  const networkMount = `${target.networkConfigPath}:/networks/network.json:ro`;

  const searchEnv = [
    `      NETWORK_CONFIG_PATH: /networks/network.json`,
    `      SWEEP_INTERVAL_MS: "${timing.SWEEP_INTERVAL_MS}"`,
    `      CACHE_TTL_SECONDS: "${timing.CACHE_TTL_SECONDS}"`,
    `      PEL_MIN_IDLE_MS: "${timing.PEL_MIN_IDLE_MS}"`,
  ].join('\n');

  // The base compose publishes fixed host ports (5432, 5555, 8080, 8025,
  // 2742, 3100) because it is built for a developer running ONE stack. A
  // harness has to coexist with whatever that developer already has up, and
  // with a run for a different target, so every published port becomes
  // ephemeral and is discovered after boot.
  //
  // `!override` matters: compose MERGES sequences, so a plain `ports:` here
  // would append to the base list and keep the fixed bindings.
  const ephemeral = (containerPort: number) =>
    `    ports: !override\n      - "0:${containerPort}"`;

  // container_name is global to the docker daemon, not scoped to the compose
  // project, so the base compose's fixed names collide with a stale run, a
  // second target, or the developer's own stack. Resetting lets compose
  // derive project-scoped names instead.
  const unnamed = '    container_name: !reset null';

  return `# GENERATED by bluedots-e2e — do not edit.
# Overlay on Signals-DPG/local-setup/docker-compose.yml for target ${target.id}.
services:
  postgres:
${unnamed}
${ephemeral(5432)}

  redis:
${unnamed}
${ephemeral(6379)}

  keycloak:
${unnamed}
${ephemeral(8080)}${
    aggregatorRoot
      ? `
    # aggregator-dpg's realm export is the only one carrying all eight
    # clients a four-service stack needs, and it must be rendered by
    # aggregator's OWN script: signals' substitutes 11 placeholders where
    # aggregator's substitutes 19, and signals' substitutes neither the realm
    # name nor any client secret. Rendering this export through signals'
    # script imports a realm literally named __KEYCLOAK_REALM__ whose clients
    # have __*_SECRET__ for secrets.
    #
    # The themes mount is replaced rather than added: signals-ui in this
    # realm sets login_theme: signals, which exists only under
    # aggregator-dpg, and aggregator's themes dir also carries otp, so it is
    # a superset.
    # !override, not a plain volumes key: compose APPENDS sequences, so
    # otherwise signals' themes and aggregator's themes both target
    # /opt/keycloak/themes and the mounts collide. Overriding drops
    # everything the base declared, so the provider jar and the named data
    # volume are restated here.
    # aggregator's render script substitutes 19 placeholders where signals'
    # substitutes 11, so it needs variables the base compose never passes to
    # this container. An .env file only feeds compose-file interpolation --
    # it does not reach the container -- so they are declared here.
    environment:
      KEYCLOAK_REALM: \${KEYCLOAK_REALM}
      AGGREGATOR_API_SECRET: \${AGGREGATOR_API_SECRET}
      AGGREGATOR_PORTAL_SECRET: \${AGGREGATOR_PORTAL_SECRET}
      AGGREGATOR_BFF_SECRET: \${AGGREGATOR_BFF_SECRET}
      SIGNALS_API_SECRET: \${SIGNALS_API_SECRET}
      CAMPAIGN_MANAGER_SECRET: \${CAMPAIGN_MANAGER_SECRET}
      VOICE_DPG_SIGNALS_SECRET: \${VOICE_DPG_SIGNALS_SECRET}
      SIGNALSTACK_CLIENT_SECRET: \${SIGNALSTACK_CLIENT_SECRET}
    volumes: !override
      - ${aggregatorRoot}/infra/keycloak/render-realm.sh:/opt/keycloak/render-realm.sh:ro
      - ${realmDir ?? `${aggregatorRoot}/infra/keycloak/realms`}:/opt/keycloak/data/import-template:ro
      - ${aggregatorRoot}/infra/keycloak/providers:/opt/keycloak/providers:ro
      - ${aggregatorRoot}/infra/keycloak/themes:/opt/keycloak/themes:ro
      - signals-keycloak-data:/opt/keycloak/data`
      : ''
  }

  mailpit:
${unnamed}
${ephemeral(8025)}
    # The base healthcheck uses /dev/tcp/127.0.0.1/8025, a bash builtin. The
    # mailpit image ships sh and no bash, so CMD-SHELL can never satisfy it
    # and the container sits permanently unhealthy -- invisible until
    # something waits on health, which up --wait does. wget is present in
    # the image and answers the same question.
    healthcheck:
      test: ["CMD-SHELL", "wget -q -O /dev/null http://127.0.0.1:8025/readyz || exit 1"]
      interval: 5s
      timeout: 3s
      retries: 20

  # Built from local-setup/infra/signals-bootstrap.Dockerfile by the base
  # compose. Naming an image here would make compose try to pull it first.
  signals-bootstrap:
${unnamed}
    environment:
      NETWORK_CONFIG_SOURCE: local
      NETWORK_CONFIG_LOCAL_FILE: /networks/network.json
    volumes:
      - ${networkMount}

  signals-api:
    image: ghcr.io/blue-dots-economy/signals-dpg/api@${digests['signals-dpg']}
    build: !reset null
${unnamed}
${ephemeral(2742)}
    environment:
      NETWORK_CONFIG_SOURCE: local
      NETWORK_CONFIG_LOCAL_FILE: /networks/network.json
    volumes:
      - ${networkMount}

  # Not needed: journeys assert over HTTP. Moving it behind an unused profile
  # keeps it defined without booting it.
  signals-ui:
    profiles: ["ui"]

  signals-search-api:
    image: ghcr.io/blue-dots-economy/signals-search@${digests['signals-search']}
${unnamed}
${ephemeral(3100)}
    environment:
${searchEnv}
    volumes:
      - ${networkMount}

  signals-search-worker:
    image: ghcr.io/blue-dots-economy/signals-search@${digests['signals-search']}
${unnamed}
    environment:
${searchEnv}
    volumes:
      - ${networkMount}
`;
}

/**
 * Fail before boot if a bind source is missing or is not a file.
 *
 * Docker creates a missing bind source as an empty DIRECTORY rather than
 * erroring, so the mistake surfaces much later as an EISDIR crash inside a
 * container, with nothing pointing back at the path that was wrong.
 */
export async function assertBindSources(paths: readonly string[]): Promise<void> {
  for (const path of paths) {
    let stats;
    try {
      stats = await stat(path);
    } catch {
      throw new Error(`Bind source does not exist: ${path}`);
    }
    if (!stats.isFile()) {
      throw new Error(`Bind source is not a file: ${path}`);
    }
  }
}
